namespace sv_c83f53a7fb6c4d55b27dc9d2dd219832.Services;

/// <summary>
/// Scoped service that holds the current warehouse selection for a single user circuit.
/// Components subscribe to <see cref="OnChange"/> to react when the warehouse changes.
/// </summary>
public class WarehouseState
{
    public static readonly IReadOnlyList<WarehouseInfo> AvailableWarehouses =
    [
        new("wh-east", "Warehouse East"),
        new("wh-west", "Warehouse West"),
        new("wh-central", "Warehouse Central"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public WarehouseInfo CurrentWarehouse =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId);

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_c83f53a7fb6c4d55b27dc9d2dd219832.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts on a timer.
/// Polling is started/stopped by the dashboard page; all subscribers
/// (including the sidebar badge) are notified when new data arrives.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _activeConsumers;

    public int CurrentAlertCount { get; private set; }

    /// <summary>
    /// Fired on a background thread — subscribers must wrap StateHasChanged
    /// in <c>InvokeAsync</c>.
    /// </summary>
    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
    }

    /// <summary>Simulates a database query returning a random low-stock count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Begins polling every 10 seconds. Multiple callers are ref-counted so
    /// the timer only runs while at least one consumer is active.
    /// </summary>
    public void StartPolling()
    {
        _activeConsumers++;
        if (_activeConsumers > 1) return;

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    /// <summary>
    /// Decrements the consumer count. Stops the timer when no consumers remain.
    /// </summary>
    public void StopPolling()
    {
        _activeConsumers = Math.Max(0, _activeConsumers - 1);
        if (_activeConsumers == 0)
        {
            CancelTimer();
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fire an initial fetch immediately so the UI isn't empty.
        await FetchAndNotifyAsync();

        while (_timer is not null && !ct.IsCancellationRequested)
        {
            try
            {
                if (!await _timer.WaitForNextTickAsync(ct))
                    break;
            }
            catch (OperationCanceledException)
            {
                break;
            }

            await FetchAndNotifyAsync();
        }
    }

    private async Task FetchAndNotifyAsync()
    {
        CurrentAlertCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnAlertCountChanged?.Invoke();
    }

    private void CancelTimer()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        CancelTimer();
    }
}

